CREATE DATABASE IF NOT EXISTS webhosting_admin CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE webhosting_admin;
CREATE TABLE IF NOT EXISTS customers(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,name VARCHAR(190) NOT NULL,email VARCHAR(190),status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS projects(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,customer_id BIGINT UNSIGNED NULL,name VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL,status ENUM('active','disabled') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_projects_slug(slug)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS domains(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,project_id BIGINT UNSIGNED NULL,domain VARCHAR(253) NOT NULL,status ENUM('active','pending','disabled') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_domains_domain(domain)) ENGINE=InnoDB;
